<?php
function tdc_layout_pdf(array $lines,array $settings):string{
 require_once __DIR__.'/../vendor/autoload.php';
 $text=static fn($s)=>iconv('UTF-8','Windows-1252//TRANSLIT',(string)$s)?:'';$font=$settings['invoice_font']??'Helvetica';if($font==='Times-Roman')$font='Times';if(!in_array($font,['Helvetica','Times','Courier'],true))$font='Helvetica';
 $hex=$settings['invoice_color']??'#3354aa';if(!preg_match('/^#[0-9a-f]{6}$/i',$hex))$hex='#3354aa';$rgb=array_map('hexdec',str_split(substr($hex,1),2));$variables=['{{client_name}}'=>'Customer','{{amount_paid}}'=>'','{{order_id}}'=>'','{{invoice_date}}'=>gmdate('Y-m-d')];foreach($lines as $line){if(str_starts_with($line,'Billed to: '))$variables['{{client_name}}']=substr($line,11);if(str_starts_with($line,'Amount: '))$variables['{{amount_paid}}']=substr($line,8);if(str_starts_with($line,'Order: #'))$variables['{{order_id}}']=substr($line,8);if(str_starts_with($line,'Date: '))$variables['{{invoice_date}}']=substr($line,6);}
 $pdf=new class extends FPDF{public array $tdcSettings=[];public array $tdcColor=[];public string $tdcFont='Helvetica';function Header(){ $this->SetFillColor(...$this->tdcColor);$this->Rect(0,0,210,28,'F');$this->SetTextColor(255,255,255);$this->SetFont($this->tdcFont,'B',20);$this->SetXY(14,9);$this->Cell(180,10,$this->tdcSettings['header'],0,1);$this->SetY(38);$this->SetTextColor(32,32,40);$this->SetFont($this->tdcFont,'',11);}function Footer(){$this->SetY(-16);$this->SetFont($this->tdcFont,'',8);$this->SetTextColor(100,100,110);$this->Cell(180,8,$this->tdcSettings['footer'].' | Page '.$this->PageNo(),0,0,'C');}};
 $pdf->tdcSettings=['header'=>$text(strtr($settings['invoice_header']??'TDC TECH',$variables)),'footer'=>$text(strtr($settings['invoice_footer']??'TDC TECH | tdctech.org',$variables))];$pdf->tdcColor=$rgb;$pdf->tdcFont=$font;$pdf->SetMargins(14,38,14);$pdf->SetAutoPageBreak(true,22);$pdf->AddPage();foreach($lines as $line)$pdf->MultiCell(182,7,$text($line));
 $temporary=[];$image=function(string $url)use(&$temporary){if(!preg_match('#^/uploads/content/[a-f0-9]+\.(png|jpg|webp|gif)$#',$url))return null;$path=__DIR__.'/../public'.$url;if(!is_file($path))return null;$info=getimagesize($path);if(!$info||$info[0]*$info[1]>25000000)return null;$source=imagecreatefromstring(file_get_contents($path));if(!$source)return null;$canvas=imagecreatetruecolor(imagesx($source),imagesy($source));imagefill($canvas,0,0,imagecolorallocate($canvas,255,255,255));imagecopy($canvas,$source,0,0,0,0,imagesx($source),imagesy($source));$file=tempnam(sys_get_temp_dir(),'tdc_pdf_');imagejpeg($canvas,$file,85);imagedestroy($canvas);imagedestroy($source);$temporary[]=$file;return $file;};
 try{
  $q=db()->query("SELECT setting_value FROM site_settings WHERE setting_key='logo_url'");if($logo=$image($q->fetchColumn()?:'')){$page=$pdf->PageNo();$pdf->Image($logo,176,4,22,20,'JPG');}
  if($pdf->GetY()>220)$pdf->AddPage();$y=$pdf->GetY()+10;$x=14;$blocks=explode(',',$settings['invoice_blocks']??'qr,barcode,signature,approval');
  foreach(array_slice(array_unique($blocks),0,4) as $block){
   if($block==='qr'&&($settings['invoice_qr']??'1')==='1'){$url='https://tdctech.org'.($variables['{{order_id}}']?'/api/document.php?order='.rawurlencode($variables['{{order_id}}']):'/profile');$options=new \chillerlan\QRCode\QROptions(['outputType'=>\chillerlan\QRCode\QRCode::OUTPUT_IMAGE_PNG,'outputBase64'=>false,'scale'=>4]);$file=tempnam(sys_get_temp_dir(),'tdc_qr_');file_put_contents($file,(new \chillerlan\QRCode\QRCode($options))->render($url));$temporary[]=$file;$pdf->Image($file,$x,$y,28,28,'PNG');$x+=43;}
   elseif($block==='barcode'&&($settings['invoice_barcode']??'1')==='1'){$generator=new \Picqer\Barcode\BarcodeGeneratorPNG();$file=tempnam(sys_get_temp_dir(),'tdc_bar_');$value=$variables['{{order_id}}']?'INV-'.$variables['{{order_id}}']:'TDC-STATEMENT';file_put_contents($file,$generator->getBarcode($value,$generator::TYPE_CODE_128));$temporary[]=$file;$pdf->Image($file,$x,$y+5,40,12,'PNG');$x+=48;}
   elseif($block==='signature'&&!empty($settings['invoice_signature'])){if($signature=$image($settings['invoice_signature'])){$pdf->Image($signature,$x,$y,38,20,'JPG');$x+=43;}}
   elseif($block==='approval'&&!empty($settings['invoice_approved_by'])){$pdf->SetXY($x,$y+5);$pdf->SetFont($font,'B',9);$pdf->MultiCell(42,5,$text('Approved By: '.$settings['invoice_approved_by']));$x+=43;}
  }
  return $pdf->Output('S');
 }finally{foreach($temporary as $file)if(is_file($file))unlink($file);}
}
